import {toWav} from './media-core.js?v=0.5.1';import {redact} from './translation-api.js?v=0.5.1';
let config={url:'',model:''},key='';
try{const saved=JSON.parse(localStorage.getItem('classbridge-cloud-speech')||'{}');config={url:String(saved.url||''),model:String(saved.model||'')};}catch{}
export function cloudConfig(){return {...config};}
export function validateCloud(input=config){let url;try{url=new URL(input.url);}catch{throw new Error('请填写云端语音识别 API 完整地址');}if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)))throw new Error('云端语音识别需 HTTPS 或本机 localhost');if(url.username||url.password||url.search||url.hash)throw new Error('语音 API 地址不能包含账号、查询参数或密钥');if(!input.model.trim())throw new Error('请填写云端语音识别模型 ID');return{url:url.href,model:input.model.trim()};}
export function saveCloud(input,secret){config=validateCloud(input);key=secret.trim();try{localStorage.setItem('classbridge-cloud-speech',JSON.stringify(config));}catch{}return {...config};}
export function clearCloudKey(){key='';}
export async function recognizeCloud(audio,direction,fetcher=fetch,input=config,secret=key){const settings=validateCloud(input),body=new FormData();body.append('file',toWav(audio),'audio.wav');body.append('model',settings.model);body.append('language',direction==='en-zh'?'en':'zh');body.append('response_format','json');const headers={};if(secret)headers.Authorization=`Bearer ${secret}`;let response;try{response=await fetcher(settings.url,{method:'POST',headers,body,credentials:'omit',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(30000)});}catch(e){throw new Error(e.name==='TimeoutError'?'云端识别超时':'无法连接云端语音 API，请检查地址、网络和 CORS');}const data=await response.json().catch(()=>null);if(!response.ok)throw new Error(redact(`云端识别 HTTP ${response.status}：${data?.error?.message||'请求失败'}`,secret));if(typeof data?.text!=='string')throw new Error('语音 API 没有返回 text 字段，请使用兼容 audio/transcriptions 的接口');return{text:data.text};}
